import assert from 'node:assert/strict';
import { createServer } from 'node:http';
import { mkdtemp, writeFile, readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { createHash } from 'node:crypto';
import { rlmLoop } from '/home/genie/orca/workspaces/genie/mikro-engine-split/mikro/dist/src/rlm.js';
import { parseCustomProviders } from '/home/genie/orca/workspaces/genie/mikro-engine-split/mikro/dist/src/custom-providers.js';
const proofRoot = await mkdtemp('/home/genie/.local/share/mikro-engine-split/experiments-g8/rlm-cap-receipt-proof-');
let requests = 0;
const server = createServer(async (req, res) => {
  for await (const _chunk of req) {}
  requests++;
  res.writeHead(200, { 'Content-Type': 'text/event-stream' });
  res.end(`data: ${JSON.stringify({ id: 'isolated-packet-fixture', object: 'chat.completion.chunk', model: 'control', choices: [{ index: 0, delta: { role: 'assistant', content: "```repl\nprint('not final')\n```" }, finish_reason: 'stop' }], usage: { prompt_tokens: 11, completion_tokens: 7, total_tokens: 18 } })}\n\ndata: [DONE]\n\n`);
});
await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
const address = server.address();
assert(address && typeof address !== 'string');
const providers = parseCustomProviders({ 'receipt-fixture': { 'base-url': `http://127.0.0.1:${address.port}/v1`, 'api-key-env': 'MIKRO_RLM_RECEIPT_FIXTURE_KEY', models: { control: { cost: { input: 1, output: 2 } } } } }, 'isolated receipt diagnostic');
process.env.MIKRO_RLM_RECEIPT_FIXTURE_KEY = 'fixture-only-not-a-credential';
const config = { system: null, tools: [], criteria: null, model: { provider: 'receipt-fixture', model: 'control', providers }, configDir: proofRoot, budget: { maxCost: null, maxTokens: null, maxDepth: 0 }, contextConfig: { extensions: ['.md'], exclude: ['node_modules'] }, toolsLevel: 'core', cache: { enabled: false, strategy: 'full', retention: 'long' }, gemini: { thinkingLevel: null, googleSearch: false, urlContext: false, codeExecution: false, computerUse: false, mapsGrounding: false, fileSearch: false, mediaResolution: null }, output: { schema: null }, storage: { enabled: 'never', mode: 'persistent', dataDir: join(proofRoot, 'data'), port: 0, chunkSize: null, chunkUtilization: 0.6, charsPerToken: 4 }, prompt: { appendStopProtocol: true }, validate: null, providers, configSource: 'yaml' };
let failure;
try { await rlmLoop('isolated no-external-inference receipt diagnostic', null, config, { maxIterations: 1, maxRetries: 0, output: 'json' }); }
catch (error) { failure = { name: error.name, message: error.message, receipt: error.receipt ?? null, usage: error.usage ?? null, iterations: error.iterations ?? null }; }
finally { delete process.env.MIKRO_RLM_RECEIPT_FIXTURE_KEY; server.closeAllConnections(); await new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve())); }
assert.equal(requests, 1);
assert(failure && /maxIterations exhausted/.test(failure.message));
const reproduced = failure.receipt === null && failure.usage === null;
const compiledPath = '/home/genie/orca/workspaces/genie/mikro-engine-split/mikro/dist/src/rlm.js';
const proof = { schemaVersion: 1, kind: 'actual-compiled-RLM-local-packet-accounting-loss-diagnosis', externalModelCalls: 0, realPython: true, realCompiledLoop: true, sourceOrArtifactModified: false, requests, observedPacketUsage: { inputTokens: 11, outputTokens: 7, totalTokens: 18, fixtureCatalogCostUsd: 0.000025, costKind: 'local-fixture-not-paid-inference' }, failure, reproduced, compiled: { path: compiledPath, sha256: createHash('sha256').update(await readFile(compiledPath)).digest('hex') }, proofRoot };
await writeFile(join(proofRoot, 'proof.json'), JSON.stringify(proof, null, 2) + '\n', { mode: 0o600, flag: 'wx' });
console.log(JSON.stringify({ proofPath: join(proofRoot, 'proof.json'), reproduced, requests, externalModelCalls: 0, failure }));
process.exitCode = reproduced ? 0 : 2;
